import json, sys, os
DB = "tablesnap.json"
def load():
    return json.load(open(DB)) if os.path.exists(DB) else {"inventory": {}, "orders": []}
def save(d): json.dump(d, open(DB, "w"), indent=2)
def main(argv):
    d = load()
    if len(argv) < 2:
        print("usage: tablesnap.py [stock NAME QTY | use NAME QTY | order ITEM:QTY,... | lowstock N | report]"); return
    cmd = argv[1]
    if cmd == "stock":
        d["inventory"][argv[2]] = d["inventory"].get(argv[2], 0) + int(argv[3])
    elif cmd == "use":
        d["inventory"][argv[2]] = d["inventory"].get(argv[2], 0) - int(argv[3])
    elif cmd == "order":
        items = dict(p.split(":") for p in argv[2].split(","))
        d["orders"].append(items)
        for k, v in items.items():
            d["inventory"][k] = d["inventory"].get(k, 0) - int(v)
    elif cmd == "lowstock":
        n = int(argv[2]) if len(argv) > 2 else 5
        for k, v in d["inventory"].items():
            if v <= n: print(f"LOW: {k} ({v})")
    elif cmd == "report":
        print(f"orders: {len(d['orders'])}")
        for k, v in sorted(d["inventory"].items()): print(f"{k}: {v}")
    save(d)
if __name__ == "__main__":
    main(sys.argv)
EOF
