#        tablesnap.py start SECTION       (begin counting a section)
#        tablesnap.py pause               (save place, safe to leave)
#        tablesnap.py resume              (show where you left off)
#        tablesnap.py low [N]             (items at or below N, default 3)
#        tablesnap.py show
def main(argv):
    d = load()
    if len(argv) < 2:
        print("usage: tablesnap.py [count ITEM QTY | start SECTION | pause | resume | low [N] | show]"); return
    cmd = argv[1]
    if cmd == "count" and len(argv) == 4:
        d["counts"][argv[2].lower()] = int(argv[3])
        if d["section"] and argv[2].lower() not in d["done"]:
            d["done"].append(argv[2].lower())
        save(d); print(f"{argv[2]}: {argv[3]}")
    elif cmd == "start" and len(argv) == 3:
        d["section"] = argv[2]; d["done"] = []; save(d); print(f"started: {argv[2]}")
    elif cmd == "pause":
        save(d); print(f"paused at section {d['section']}, {len(d['done'])} items done")
    elif cmd == "resume":
        if not d["section"]: print("nothing in progress"); return
        print(f"resuming section {d['section']}; already counted: {', '.join(d['done']) or 'none'}")
    elif cmd == "low":
        n = int(argv[2]) if len(argv) > 2 else 3
        for k, v in sorted(d["counts"].items()):
            if v <= n: print(f"LOW: {k} ({v})")
    elif cmd == "show":
        for k, v in sorted(d["counts"].items()): print(f"{k}: {v}")
if __name__ == "__main__":
    main(sys.argv)
